    auto require=[](bool ok,const char* why){if(!ok)throw std::runtime_error(why);};
    auto now=[](){return App::now();};
    auto saveImage=[&](Bitmap& image,const std::string& path){UINT count=0,size=0;GetImageEncodersSize(&count,&size);std::vector<uint8_t> memory(size);auto codecs=(ImageCodecInfo*)memory.data();GetImageEncoders(count,size,codecs);for(UINT i=0;i<count;++i)if(wcscmp(codecs[i].MimeType,L"image/png")==0){require(image.Save(W(path).c_str(),&codecs[i].Clsid,0)==Ok,"save preview image");return;}throw std::runtime_error("PNG encoder");};
    std::ofstream log(dir+"/checks.txt");
