        Session text;ObjectId caption,oxygen;require(text.doc.addText(Vec2(),14,"文字旋转 Test",&caption).ok(),"text fixture");require(text.doc.addAtom(Vec2(60,40),8,&oxygen).ok(),"oxygen fixture");text.refresh();auto original=text.doc.digest();Box before;for(const auto& p:text.scene.primitives())if(p.source==ObjectRef(ObjectKind::Text,caption)){before.add(p.bounds.min);before.add(p.bounds.max);}
