        require(after.height()>after.width()*2&&before.width()>before.height()*2,"caption rotates its glyphs");auto angle=static_cast<const Document&>(text.doc).extensions(ObjectRef(ObjectKind::Text,caption)).findValue("studio.text.RotationAngle");require(angle&&std::abs(std::atof(angle->c_str())/65536-90)<1e-8,"stored text angle");auto rotated=text.doc.digest();require(text.undo().ok()&&text.doc.digest()==original,"text rotation undo");require(text.undo(true).ok()&&text.doc.digest()==rotated,"text rotation redo");require(text.save(dir+"/rotated-text.cdxml",true).ok(),"save text rotation");Session back;require(back.open(dir+"/rotated-text.cdxml").ok(),"reopen text rotation");auto restored=static_cast<const Document&>(back.doc).extensions(ObjectRef(ObjectKind::Text,0)).findValue("studio.text.RotationAngle");require(restored&&std::abs(std::atof(restored->c_str())/65536-90)<1e-8,"CDXML retains text angle");
