        for(const auto& atom:drawing.doc.atoms().records())if(atom.isAlive()&&!visited.count(atom.id)){std::vector<ObjectId> component(1,atom.id);visited.insert(atom.id);for(size_t i=0;i<component.size();++i)for(auto id:drawing.doc.neighbours(component[i]))if(visited.insert(id).second)component.push_back(id);if(component.size()<=120&&component.size()>largest.size())largest=component;}
        Session subset;std::vector<ObjectRef> chosen;for(auto id:largest)chosen.push_back(ObjectRef(ObjectKind::Atom,id));require(studioio::append(drawing.doc,subset.doc,chosen,Vec2(),nullptr).ok(),"extract NMR structure");std::string source;require(studioio::exportXml(subset.doc,&source).ok(),"NMR snapshot");tinyxml2::XMLDocument xml;require(xml.Parse(source.c_str())==tinyxml2::XML_SUCCESS,"parse snapshot");std::vector<int> ids;std::function<void(tinyxml2::XMLElement*)> visit=[&](tinyxml2::XMLElement* p){if(std::string(p->Name())=="n")ids.push_back(p->IntAttribute("id"));for(auto c=p->FirstChildElement();c;c=c->NextSiblingElement())visit(c);};visit(xml.RootElement());std::ostringstream sample;sample<<"NMR1H\t1\nmapping\t1\nsolvent\tcdcl3\nformula\tRendering fixture\ncoverage\t"<<ids.size()<<"\t"<<ids.size()<<"\n";for(size_t i=0;i<ids.size();++i)sample<<"peak\t"<<.1+i*.13<<"\t1\t"<<ids[i]<<"\ts\tRendering fixture\tgood\t0\t0\n";
        NmrDialog nmr;require(nmr.parse(sample.str())&&nmr.prepareStructure(source),"dense annotated preview");nmr.source=source;
