        double legacy=0,accelerated=0;for(int pass=0;pass<2;++pass){nmr.legacyPreview=pass==0;for(int frame=0;frame<8;++frame){nmr.structureZoom=1+frame*.08;nmr.structurePan=Vec2(frame*3,frame*2);double start=now();nmr.paint(window,dc);double elapsed=now()-start;if(pass==0)legacy+=elapsed;else if(frame>0)accelerated+=elapsed;}}
        saveImage(*nmr.paintBuffer,dir+"/nmr-preview.png");uint64_t structureFrames=nmr.structureFrames;RECT chartDirty={LONG(chart.X),LONG(chart.Y),LONG(std::ceil(chart.GetRight())),LONG(std::ceil(chart.GetBottom()))};double chartMs=0;for(int i=0;i<12;++i){nmr.zoomChart(chart,chart.X+chart.Width*.5,1.02);double start=now();nmr.paint(window,dc,&chartDirty);chartMs+=now()-start;}require(nmr.structureFrames==structureFrames,"chart-only zoom does not redraw molecule");
        uint64_t chartFrames=nmr.chartFrames;RECT moleculeDirty={LONG(molecule.X),LONG(molecule.Y),LONG(std::ceil(molecule.GetRight())),LONG(std::ceil(molecule.GetBottom()))};for(int i=0;i<4;++i){nmr.structureZoom*=1.01;nmr.paint(window,dc,&moleculeDirty);}require(nmr.chartFrames==chartFrames,"structure-only zoom does not redraw chart");ReleaseDC(window,dc);DestroyWindow(window);
        log<<"nmr_atoms="<<ids.size()<<" legacy_full_ms="<<legacy/8<<" cached_full_ms="<<accelerated/7<<" chart_only_ms="<<chartMs/12<<" independent_repaint=1\n";log.flush();
        // Real tab host with an asynchronous predictor. While it is busy,
